function climbStairs(n) {
  let prev = 1;   // ways to reach step i - 2
  let curr = 1;   // ways to reach step i - 1
  for (let i = 2; i <= n; i++) {
    const next = prev + curr;
    prev = curr;
    curr = next;
  }
  return curr;
}

